package com.oveduumnakal.implingpathfinder;

/** How fast the impling highlight pulses, or {@link #SOLID} for no pulse at all. */
public enum GlowSpeed
{
	/** One pulse every 2.4 seconds. */
	SLOW("Slow", 2400),

	/** One pulse every 1.2 seconds. */
	MEDIUM("Medium", 1200),

	/** One pulse every 0.6 seconds. */
	FAST("Fast", 600),

	/** No pulse: the highlight stays at full strength. */
	SOLID("Solid", 0);

	private final String name;

	private final int periodMillis;

	GlowSpeed(String name, int periodMillis)
	{
		this.name = name;
		this.periodMillis = periodMillis;
	}

	/**
	 * Milliseconds for one full pulse.
	 *
	 * @return the pulse period, or 0 for {@link #SOLID}
	 */
	int getPeriodMillis()
	{
		return periodMillis;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

