package com.oveduumnakal.implingpathfinder;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws each route on the minimap as a line ending in a dot on the impling. */
class ImplingMinimapOverlay extends Overlay
{
	private static final int DOT_SIZE = 5;

	/** The minimap draw area in each game layout: fixed, resizable classic, resizable modern. */
	private static final int[] MINIMAP_WIDGETS = {
		InterfaceID.Toplevel.MINIMAP,
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP,
	};

	private final Client client;

	private final ImplingPathfinderPlugin plugin;

	private final ImplingPathfinderConfig config;

	@Inject
	ImplingMinimapOverlay(Client client, ImplingPathfinderPlugin plugin, ImplingPathfinderConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Shape clip = config.showMinimap() ? minimapClip() : null;
		if (clip == null)
			return null;

		Shape previousClip = graphics.getClip();
		graphics.setClip(clip);
		graphics.setStroke(new BasicStroke(config.lineThickness(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (ImplingRoute route : plugin.getRoutes())
		{
			graphics.setColor(plugin.colorOf(route.getType()));
			Point previous = null;
			for (LocalPoint tile : route.getTiles())
			{
				Point point = Perspective.localToMinimap(client, tile);
				if (point != null && previous != null)
					graphics.drawLine(previous.getX(), previous.getY(), point.getX(), point.getY());

				previous = point;
			}

			if (previous != null)
				graphics.fillOval(previous.getX() - DOT_SIZE / 2, previous.getY() - DOT_SIZE / 2, DOT_SIZE, DOT_SIZE);
		}

		graphics.setClip(previousClip);
		return null;
	}

	/** The round minimap area of whichever layout is showing, so lines never spill past its edge. */
	private Shape minimapClip()
	{
		for (int id : MINIMAP_WIDGETS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				Rectangle bounds = widget.getBounds();
				return new Ellipse2D.Double(bounds.getX(), bounds.getY(), bounds.getWidth(), bounds.getHeight());
			}
		}

		return null;
	}
}

