package com.oveduumnakal.implingpathfinder;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws each route on the ground as a line in its impling's colour. Over any wheat pushed through, the tile is
 * outlined and the line carries on across it at the wheat tile's opacity. Outlines the target impling's tile and
 * makes its clickbox glow.
 */
class ImplingPathOverlay extends Overlay
{
	/** Colour of a wheat tile the route pushes through: #F9FF97 at half opacity. */
	static final Color WHEAT_COLOR = new Color(0xF9, 0xFF, 0x97, 0x80);

	private static final int FILL_ALPHA_DIVISOR = 4;

	private final Client client;

	private final ImplingPathfinderPlugin plugin;

	private final ImplingPathfinderConfig config;

	@Inject
	ImplingPathOverlay(Client client, ImplingPathfinderPlugin plugin, ImplingPathfinderConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Stroke stroke = new BasicStroke(config.lineThickness(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		WorldView view = client.getTopLevelWorldView();
		int plane = view.getPlane();
		double glow = HighlightStyle.pulse(System.currentTimeMillis(), config.glowSpeed());
		for (ImplingRoute route : plugin.getRoutes())
		{
			Color color = plugin.colorOf(route.getType());
			List<Polygon> wheat = wheatPolygons(route);
			Area wheatArea = new Area();
			for (Polygon tile : wheat)
				wheatArea.add(new Area(tile));

			Shape previousClip = graphics.getClip();
			Area outside = new Area(previousClip == null ? canvasBounds() : previousClip);
			outside.subtract(wheatArea);
			graphics.setClip(outside);
			drawLine(graphics, route.getTiles(), color, stroke, plane);
			graphics.setClip(previousClip);
			for (Polygon tile : wheat)
				drawShape(graphics, tile, WHEAT_COLOR, stroke);

			if (!wheat.isEmpty())
			{
				graphics.clip(wheatArea);
				double wheatShare = WHEAT_COLOR.getAlpha() / 255.0;
				drawLine(graphics, route.getTiles(), HighlightStyle.scale(color, wheatShare), stroke, plane);
				graphics.setClip(previousClip);
			}

			drawImplingTile(graphics, route, view, color, stroke);
			HighlightStyle.draw(graphics, route.getNpc().getConvexHull(), color, glow, stroke);
		}

		return null;
	}

	/** Outlines the tile the impling stands on (its true server tile, not its in-between drawn position). */
	private void drawImplingTile(Graphics2D graphics, ImplingRoute route, WorldView view, Color color, Stroke stroke)
	{
		LocalPoint tile = LocalPoint.fromWorld(view, route.getNpc().getWorldLocation());
		Polygon poly = tile == null ? null : Perspective.getCanvasTilePoly(client, tile);
		if (poly != null)
			drawShape(graphics, poly, color, stroke);
	}

	private List<Polygon> wheatPolygons(ImplingRoute route)
	{
		List<Polygon> polygons = new ArrayList<>();
		for (LocalPoint tile : route.getWheatTiles())
		{
			Polygon poly = Perspective.getCanvasTilePoly(client, tile);
			if (poly != null)
				polygons.add(poly);
		}

		return polygons;
	}

	private Rectangle canvasBounds()
	{
		return new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
	}

	/** Draws the route line through each tile's middle, within whatever clip is set. */
	private void drawLine(Graphics2D graphics, List<LocalPoint> tiles, Color color, Stroke stroke, int plane)
	{
		graphics.setColor(color);
		graphics.setStroke(stroke);
		Point previous = null;
		for (LocalPoint tile : tiles)
		{
			Point point = Perspective.localToCanvas(client, tile, plane);
			if (point != null && previous != null)
				graphics.drawLine(previous.getX(), previous.getY(), point.getX(), point.getY());

			previous = point;
		}
	}

	private static void drawShape(Graphics2D graphics, Shape shape, Color color, Stroke stroke)
	{
		int alpha = color.getAlpha() / FILL_ALPHA_DIVISOR;
		Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
		OverlayUtil.renderPolygon(graphics, shape, color, fill, stroke);
	}
}

