package com.oveduumnakal.implingpathfinder;

import java.awt.Color;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/** Settings for Impling Pathfinder: which impling kinds to route to, in what colour, and how the route is drawn. */
@ConfigGroup(ImplingPathfinderConfig.GROUP)
public interface ImplingPathfinderConfig extends Config
{
	/** Config group key, shared with the plugin so both agree on where settings are stored. */
	String GROUP = "implingpathfinder";

	/** Which implings get a route. */
	enum RouteMode
	{
		/** One route, to the selected impling with the shortest walk. */
		NEAREST("Nearest only"),
		/** A route to every selected impling in view. */
		ALL("Every impling");

		private final String label;

		RouteMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** Section holding one checkbox per impling kind. */
	@ConfigSection(
		name = "Impling types",
		description = "Pick the implings you want a route to.",
		position = 0
	)
	String TYPES_SECTION = "types";

	/** Section holding one colour per impling kind. */
	@ConfigSection(
		name = "Colours",
		description = "The colour of each impling's route and highlight.",
		position = 1
	)
	String COLORS_SECTION = "colors";

	/** Section holding the route drawing options. */
	@ConfigSection(
		name = "Route",
		description = "How the route is chosen and drawn.",
		position = 2
	)
	String ROUTE_SECTION = "route";

	/**
	 * Whether baby implings get a route.
	 *
	 * @return true to route to baby implings
	 */
	@ConfigItem(
		keyName = "baby",
		name = "Baby",
		description = "Route to baby implings.",
		position = 0,
		section = TYPES_SECTION
	)
	default boolean baby()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for baby implings.
	 *
	 * @return the baby impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "babyColor",
		name = "Baby",
		description = "Colour of the route to baby implings.",
		position = 0,
		section = COLORS_SECTION
	)
	default Color babyColor()
	{
		return new Color(255, 140, 198);
	}

	/**
	 * Whether young implings get a route.
	 *
	 * @return true to route to young implings
	 */
	@ConfigItem(
		keyName = "young",
		name = "Young",
		description = "Route to young implings.",
		position = 1,
		section = TYPES_SECTION
	)
	default boolean young()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for young implings.
	 *
	 * @return the young impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "youngColor",
		name = "Young",
		description = "Colour of the route to young implings.",
		position = 1,
		section = COLORS_SECTION
	)
	default Color youngColor()
	{
		return new Color(255, 255, 255);
	}

	/**
	 * Whether gourmet implings get a route.
	 *
	 * @return true to route to gourmet implings
	 */
	@ConfigItem(
		keyName = "gourmet",
		name = "Gourmet",
		description = "Route to gourmet implings.",
		position = 2,
		section = TYPES_SECTION
	)
	default boolean gourmet()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for gourmet implings.
	 *
	 * @return the gourmet impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "gourmetColor",
		name = "Gourmet",
		description = "Colour of the route to gourmet implings.",
		position = 2,
		section = COLORS_SECTION
	)
	default Color gourmetColor()
	{
		return new Color(255, 150, 0);
	}

	/**
	 * Whether earth implings get a route.
	 *
	 * @return true to route to earth implings
	 */
	@ConfigItem(
		keyName = "earth",
		name = "Earth",
		description = "Route to earth implings.",
		position = 3,
		section = TYPES_SECTION
	)
	default boolean earth()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for earth implings.
	 *
	 * @return the earth impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "earthColor",
		name = "Earth",
		description = "Colour of the route to earth implings.",
		position = 3,
		section = COLORS_SECTION
	)
	default Color earthColor()
	{
		return new Color(0, 140, 0);
	}

	/**
	 * Whether essence implings get a route.
	 *
	 * @return true to route to essence implings
	 */
	@ConfigItem(
		keyName = "essence",
		name = "Essence",
		description = "Route to essence implings.",
		position = 4,
		section = TYPES_SECTION
	)
	default boolean essence()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for essence implings.
	 *
	 * @return the essence impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "essenceColor",
		name = "Essence",
		description = "Colour of the route to essence implings.",
		position = 4,
		section = COLORS_SECTION
	)
	default Color essenceColor()
	{
		return new Color(0, 220, 255);
	}

	/**
	 * Whether eclectic implings get a route.
	 *
	 * @return true to route to eclectic implings
	 */
	@ConfigItem(
		keyName = "eclectic",
		name = "Eclectic",
		description = "Route to eclectic implings.",
		position = 5,
		section = TYPES_SECTION
	)
	default boolean eclectic()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for eclectic implings.
	 *
	 * @return the eclectic impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "eclecticColor",
		name = "Eclectic",
		description = "Colour of the route to eclectic implings.",
		position = 5,
		section = COLORS_SECTION
	)
	default Color eclecticColor()
	{
		return new Color(150, 255, 0);
	}

	/**
	 * Whether nature implings get a route.
	 *
	 * @return true to route to nature implings
	 */
	@ConfigItem(
		keyName = "nature",
		name = "Nature",
		description = "Route to nature implings.",
		position = 6,
		section = TYPES_SECTION
	)
	default boolean nature()
	{
		return false;
	}

	/**
	 * Colour of the route and highlight for nature implings.
	 *
	 * @return the nature impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "natureColor",
		name = "Nature",
		description = "Colour of the route to nature implings.",
		position = 6,
		section = COLORS_SECTION
	)
	default Color natureColor()
	{
		return new Color(0, 255, 180);
	}

	/**
	 * Whether magpie implings get a route.
	 *
	 * @return true to route to magpie implings
	 */
	@ConfigItem(
		keyName = "magpie",
		name = "Magpie",
		description = "Route to magpie implings.",
		position = 7,
		section = TYPES_SECTION
	)
	default boolean magpie()
	{
		return true;
	}

	/**
	 * Colour of the route and highlight for magpie implings.
	 *
	 * @return the magpie impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "magpieColor",
		name = "Magpie",
		description = "Colour of the route to magpie implings.",
		position = 7,
		section = COLORS_SECTION
	)
	default Color magpieColor()
	{
		return new Color(255, 240, 40);
	}

	/**
	 * Whether ninja implings get a route.
	 *
	 * @return true to route to ninja implings
	 */
	@ConfigItem(
		keyName = "ninja",
		name = "Ninja",
		description = "Route to ninja implings.",
		position = 8,
		section = TYPES_SECTION
	)
	default boolean ninja()
	{
		return true;
	}

	/**
	 * Colour of the route and highlight for ninja implings.
	 *
	 * @return the ninja impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "ninjaColor",
		name = "Ninja",
		description = "Colour of the route to ninja implings.",
		position = 8,
		section = COLORS_SECTION
	)
	default Color ninjaColor()
	{
		return new Color(130, 0, 255);
	}

	/**
	 * Whether crystal implings get a route.
	 *
	 * @return true to route to crystal implings
	 */
	@ConfigItem(
		keyName = "crystal",
		name = "Crystal",
		description = "Route to crystal implings (Prifddinas).",
		position = 9,
		section = TYPES_SECTION
	)
	default boolean crystal()
	{
		return true;
	}

	/**
	 * Colour of the route and highlight for crystal implings.
	 *
	 * @return the crystal impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "crystalColor",
		name = "Crystal",
		description = "Colour of the route to crystal implings.",
		position = 9,
		section = COLORS_SECTION
	)
	default Color crystalColor()
	{
		return new Color(0, 110, 255);
	}

	/**
	 * Whether dragon implings get a route.
	 *
	 * @return true to route to dragon implings
	 */
	@ConfigItem(
		keyName = "dragon",
		name = "Dragon",
		description = "Route to dragon implings.",
		position = 10,
		section = TYPES_SECTION
	)
	default boolean dragon()
	{
		return true;
	}

	/**
	 * Colour of the route and highlight for dragon implings.
	 *
	 * @return the dragon impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "dragonColor",
		name = "Dragon",
		description = "Colour of the route to dragon implings.",
		position = 10,
		section = COLORS_SECTION
	)
	default Color dragonColor()
	{
		return new Color(255, 0, 0);
	}

	/**
	 * Whether lucky implings get a route.
	 *
	 * @return true to route to lucky implings
	 */
	@ConfigItem(
		keyName = "lucky",
		name = "Lucky",
		description = "Route to lucky implings.",
		position = 11,
		section = TYPES_SECTION
	)
	default boolean lucky()
	{
		return true;
	}

	/**
	 * Colour of the route and highlight for lucky implings.
	 *
	 * @return the lucky impling colour, with alpha
	 */
	@Alpha
	@ConfigItem(
		keyName = "luckyColor",
		name = "Lucky",
		description = "Colour of the route to lucky implings.",
		position = 11,
		section = COLORS_SECTION
	)
	default Color luckyColor()
	{
		return new Color(255, 0, 200);
	}

	/**
	 * Whether to route to the nearest selected impling only, or to all of them.
	 *
	 * @return the route mode
	 */
	@ConfigItem(
		keyName = "routeMode",
		name = "Route to",
		description = "Nearest only: one route, to the selected impling with the shortest walk.\n"
			+ "Every impling: a route to each selected impling in view.",
		position = 0,
		section = ROUTE_SECTION
	)
	default RouteMode routeMode()
	{
		return RouteMode.NEAREST;
	}

	/**
	 * Whether the route is also drawn on the minimap.
	 *
	 * @return true to draw on the minimap
	 */
	@ConfigItem(
		keyName = "showMinimap",
		name = "Show on minimap",
		description = "Also draws the route on the minimap.",
		position = 1,
		section = ROUTE_SECTION
	)
	default boolean showMinimap()
	{
		return true;
	}

	/**
	 * Width of the route line, in pixels.
	 *
	 * @return the line thickness
	 */
	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "lineThickness",
