import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Entry point: tracks implings and Puro-Puro wheat in view and, every game tick, finds the quickest route to the
 * selected implings.
 */
@PluginDescriptor(
	name = "Impling Pathfinder",
	description = "Draws the walking route from you to the nearest impling of the types you pick",
	tags = {"impling", "implings", "hunter", "puro", "path", "route", "crystal", "dragon", "lucky"}
)
public class ImplingPathfinderPlugin extends Plugin
{
	/** Puro-Puro wheat that offers Push-through (ids read from the game cache's object definitions). */
	private static final Set<Integer> PUSHABLE_WHEAT = Set.of(
		ObjectID.II_MAZE_WHEAT_NO_BLOCK1,
		ObjectID.II_MAZE_WHEAT_BLOCK1,
		ObjectID.II_MAZE_WHEAT_BLOCK2,
		ObjectID.II_MAZE_WHEAT_BLOCK_MOVEABLE1,
		ObjectID.II_MAZE_WHEAT_INVIS);

	/** Route cost of one tile while running, in half game ticks (running covers two tiles a tick). */
	private static final int RUN_STEP_COST = 1;

	/** Route cost of one tile while walking, in half game ticks. */
	private static final int WALK_STEP_COST = 2;

	/**
	 * Route cost of one push through wheat, in half game ticks. A push takes 6, 8 or 10 ticks depending on a
	 * Strength roll (3 fewer with Farmer's Affinity); 8 is the middle case.
	 */
	private static final int PUSH_COST = 16;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ImplingPathfinderConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ImplingPathOverlay pathOverlay;

	@Inject
	private ImplingMinimapOverlay minimapOverlay;

	/** Implings currently in the scene, kept up to date from spawn, despawn and change events. */
	private final Set<NPC> implings = new HashSet<>();

	/** Pushable wheat currently in the scene, kept up to date from object spawn and despawn events. */
	private final Set<TileObject> wheat = new HashSet<>();

	private Set<ImplingType> selectedTypes = EnumSet.noneOf(ImplingType.class);

	private Map<ImplingType, Color> typeColors = new EnumMap<>(ImplingType.class);

	private List<ImplingRoute> routes = Collections.emptyList();

	@Provides
	ImplingPathfinderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ImplingPathfinderConfig.class);
	}

	@Override
	protected void startUp()
	{
		readTypeSettings();
		overlayManager.add(pathOverlay);
		overlayManager.add(minimapOverlay);
		clientThread.invoke(this::seedScene);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(pathOverlay);
		overlayManager.remove(minimapOverlay);
		implings.clear();
		wheat.clear();
		routes = Collections.emptyList();
	}

	/**
	 * Routes found on the last game tick, nearest first.
	 *
	 * @return the routes to draw; empty when no selected impling is in view
	 */
	List<ImplingRoute> getRoutes()
	{
		return routes;
	}

	/**
	 * Colour the player picked for an impling kind.
	 *
	 * @param type the impling kind
	 * @return the colour for its route and highlight
	 */
	Color colorOf(ImplingType type)
	{
		return typeColors.getOrDefault(type, Color.WHITE);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ImplingPathfinderConfig.GROUP.equals(event.getGroup()))
			readTypeSettings();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING)
			wheat.clear();

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			implings.clear();
			wheat.clear();
			routes = Collections.emptyList();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		trackWheat(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		wheat.remove(event.getGameObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		trackWheat(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		wheat.remove(event.getGroundObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		track(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		implings.remove(event.getNpc());
		track(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		implings.remove(event.getNpc());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		routes = findRoutes();
	}

	/** Picks up implings and wheat already in view when the plugin starts mid-session. */
	private void seedScene()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
			return;

		WorldView view = client.getTopLevelWorldView();
		for (NPC npc : view.npcs())
			track(npc);

		Scene scene = view.getScene();
		for (Tile[] column : scene.getTiles()[view.getPlane()])
		{
			for (Tile tile : column)
				seedTile(tile);
		}
	}

	private void seedTile(Tile tile)
	{
		if (tile == null)
			return;

		trackWheat(tile.getGroundObject());
		for (GameObject object : tile.getGameObjects())
			trackWheat(object);
	}

	private void trackWheat(TileObject object)
	{
		if (object != null && PUSHABLE_WHEAT.contains(object.getId()))
			wheat.add(object);
	}

	private void track(NPC npc)
	{
		if (ImplingType.fromNpcId(npc.getId()) != null)
			implings.add(npc);
	}

	private List<ImplingRoute> findRoutes()
	{
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (player == null || view == null || implings.isEmpty() || selectedTypes.isEmpty())
			return Collections.emptyList();

		LocalPoint start = LocalPoint.fromWorld(view, player.getWorldLocation());
		CollisionData[] maps = view.getCollisionMaps();
		int plane = view.getPlane();
		if (start == null || maps == null || maps[plane] == null)
			return Collections.emptyList();

		List<NPC> targets = new ArrayList<>();
		for (NPC npc : implings)
		{
			if (isRoutable(npc, view, plane))
				targets.add(npc);
		}

		if (targets.isEmpty())
			return Collections.emptyList();

		int[][] flags = maps[plane].getFlags();
		boolean[][] pushable = config.pushThroughWheat() ? pushableTiles(flags, view, plane) : null;
		int stepCost = client.getVarpValue(VarPlayerID.OPTION_RUN) == 1 ? RUN_STEP_COST : WALK_STEP_COST;
		ScenePathfinder search = ScenePathfinder.search(flags, pushable, start.getSceneX(), start.getSceneY(),
			stepCost, PUSH_COST);
		List<ImplingRoute> found = new ArrayList<>();
		for (NPC npc : targets)
		{
			LocalPoint goal = LocalPoint.fromWorld(view, npc.getWorldLocation());
			List<Point> path = search.pathTo(goal.getSceneX(), goal.getSceneY());
			if (path.isEmpty())
				continue;

			List<LocalPoint> tiles = new ArrayList<>(path.size());
			List<LocalPoint> wheatTiles = new ArrayList<>();
			for (Point tile : path)
			{
				LocalPoint local = LocalPoint.fromScene(tile.x, tile.y, view);
				tiles.add(local);
				if (isPushedWheat(flags, pushable, tile))
					wheatTiles.add(local);
			}

			int cost = search.costTo(goal.getSceneX(), goal.getSceneY());
			boolean reaches = cost != ScenePathfinder.UNREACHED;
			found.add(new ImplingRoute(npc, ImplingType.fromNpcId(npc.getId()), tiles, wheatTiles, cost, reaches));
		}

		found.sort(Comparator.comparing((ImplingRoute route) -> !route.reachesImpling())
			.thenComparingInt(ImplingRoute::getCost));
		if (config.routeMode() == ImplingPathfinderConfig.RouteMode.NEAREST && found.size() > 1)
			return List.of(found.get(0));

		return List.copyOf(found);
	}

	/**
	 * Whether a route tile is wheat the route pushes through. Only blocking wheat counts: wheat that does not block
	 * is walked over like open ground, so a route never pushes through it.
	 */
	private static boolean isPushedWheat(int[][] flags, boolean[][] pushable, Point tile)
	{
		return pushable != null && pushable[tile.x][tile.y]
			&& (flags[tile.x][tile.y] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0;
	}

	/**
	 * Marks the scene tiles holding pushable wheat on the current plane.
	 *
	 * @return the pushable grid, or {@code null} when no wheat is in view
	 */
	private boolean[][] pushableTiles(int[][] flags, WorldView view, int plane)
	{
		if (wheat.isEmpty())
			return null;

		boolean[][] pushable = new boolean[flags.length][flags[0].length];
		for (TileObject object : wheat)
		{
			LocalPoint location = object.getLocalLocation();
			int x = location.getSceneX();
			int y = location.getSceneY();
			boolean inScene = x >= 0 && y >= 0 && x < flags.length && y < flags[0].length;
			if (inScene && object.getWorldView() == view && object.getPlane() == plane)
				pushable[x][y] = true;
		}

		return pushable;
	}

	private boolean isRoutable(NPC npc, WorldView view, int plane)
	{
		ImplingType type = ImplingType.fromNpcId(npc.getId());
		if (type == null || !selectedTypes.contains(type) || npc.getWorldView() != view)
			return false;

		WorldPoint location = npc.getWorldLocation();
		return location.getPlane() == plane && LocalPoint.fromWorld(view, location) != null;
	}

	/** Re-reads which impling kinds are ticked and each kind's colour. */
	private void readTypeSettings()
	{
		Set<ImplingType> types = EnumSet.noneOf(ImplingType.class);
		Map<ImplingType, Color> colors = new EnumMap<>(ImplingType.class);
		read(types, colors, ImplingType.BABY, config.baby(), config.babyColor());
		read(types, colors, ImplingType.YOUNG, config.young(), config.youngColor());
		read(types, colors, ImplingType.GOURMET, config.gourmet(), config.gourmetColor());
		read(types, colors, ImplingType.EARTH, config.earth(), config.earthColor());
		read(types, colors, ImplingType.ESSENCE, config.essence(), config.essenceColor());
		read(types, colors, ImplingType.ECLECTIC, config.eclectic(), config.eclecticColor());
		read(types, colors, ImplingType.NATURE, config.nature(), config.natureColor());
		read(types, colors, ImplingType.MAGPIE, config.magpie(), config.magpieColor());
		read(types, colors, ImplingType.NINJA, config.ninja(), config.ninjaColor());
		read(types, colors, ImplingType.CRYSTAL, config.crystal(), config.crystalColor());
		read(types, colors, ImplingType.DRAGON, config.dragon(), config.dragonColor());
		read(types, colors, ImplingType.LUCKY, config.lucky(), config.luckyColor());
		selectedTypes = types;
		typeColors = colors;
	}

	private static void read(Set<ImplingType> types, Map<ImplingType, Color> colors, ImplingType type,
		boolean enabled, Color color)
	{
		colors.put(type, color);
		if (enabled)
			types.add(type);
	}
}

