package com.oveduumnakal.implingpathfinder;

import java.util.List;

import net.runelite.api.NPC;
import net.runelite.api.coords.LocalPoint;

/** One computed walking route from the player to an impling, as the overlays draw it. */
public final class ImplingRoute
{
	private final NPC npc;

	private final ImplingType type;

	private final List<LocalPoint> tiles;

	private final List<LocalPoint> wheatTiles;

	private final int cost;

	private final boolean reachesImpling;

	/**
	 * Creates a route.
	 *
	 * @param npc the impling the route leads to
	 * @param type the impling's kind
	 * @param tiles the tiles on the route, player's tile first
	 * @param wheatTiles the route tiles that are wheat pushed through
	 * @param cost cost of the route in half game ticks
	 * @param reachesImpling false when no walking route exists and the route stops at the closest reachable tile
	 */
	public ImplingRoute(NPC npc, ImplingType type, List<LocalPoint> tiles, List<LocalPoint> wheatTiles, int cost,
		boolean reachesImpling)
	{
		this.npc = npc;
		this.type = type;
		this.tiles = List.copyOf(tiles);
		this.wheatTiles = List.copyOf(wheatTiles);
		this.cost = cost;
		this.reachesImpling = reachesImpling;
	}

	/**
	 * The impling the route leads to.
	 *
	 * @return the impling NPC
	 */
	public NPC getNpc()
	{
		return npc;
	}

	/**
	 * The impling's kind.
	 *
	 * @return the impling kind
	 */
	public ImplingType getType()
	{
		return type;
	}

	/**
	 * The tiles on the route, player's tile first, including any wheat tiles pushed through.
	 *
	 * @return the route tiles
	 */
	public List<LocalPoint> getTiles()
	{
		return tiles;
	}

	/**
	 * The route tiles that are Puro-Puro wheat pushed through; also present in {@link #getTiles()}.
	 *
	 * @return the wheat tiles crossed by a push
	 */
	public List<LocalPoint> getWheatTiles()
	{
		return wheatTiles;
	}

	/**
	 * Cost of the route: half game ticks of travel, pushes through wheat included.
	 *
	 * @return the route cost
	 */
	public int getCost()
	{
		return cost;
	}

	/**
	 * Whether the route ends on the impling's tile.
	 *
	 * @return false when the impling is out of walking reach and the route stops short
	 */
	public boolean reachesImpling()
	{
		return reachesImpling;
	}
}

