package com.oveduumnakal.implingpathfinder;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import net.runelite.api.gameval.NpcID;

/** The impling kinds the plugin can route to, each with every NPC id it appears as (overworld and Puro-Puro). */
public enum ImplingType
{
	BABY("Baby", NpcID.II_IMPLING_TYPE_1, NpcID.II_IMPLING_TYPE_1_MAZE),
	YOUNG("Young", NpcID.II_IMPLING_TYPE_2, NpcID.II_IMPLING_TYPE_2_MAZE),
	GOURMET("Gourmet", NpcID.II_IMPLING_TYPE_3, NpcID.II_IMPLING_TYPE_3_MAZE),
	EARTH("Earth", NpcID.II_IMPLING_TYPE_4, NpcID.II_IMPLING_TYPE_4_MAZE),
	ESSENCE("Essence", NpcID.II_IMPLING_TYPE_5, NpcID.II_IMPLING_TYPE_5_MAZE),
	ECLECTIC("Eclectic", NpcID.II_IMPLING_TYPE_6, NpcID.II_IMPLING_TYPE_6_MAZE),
	NATURE("Nature", NpcID.II_IMPLING_TYPE_7, NpcID.II_IMPLING_TYPE_7_MAZE),
	MAGPIE("Magpie", NpcID.II_IMPLING_TYPE_8, NpcID.II_IMPLING_TYPE_8_MAZE),
	NINJA("Ninja", NpcID.II_IMPLING_TYPE_9, NpcID.II_IMPLING_TYPE_9_MAZE),
	CRYSTAL("Crystal",
		NpcID.II_IMPLING_TYPE_12_JOHNNY, NpcID.II_IMPLING_TYPE_12_JUNIOR, NpcID.II_IMPLING_TYPE_12_ANDY,
		NpcID.II_IMPLING_TYPE_12_JOEY, NpcID.II_IMPLING_TYPE_12_TROUBLE, NpcID.II_IMPLING_TYPE_12_HINGY,
		NpcID.II_IMPLING_TYPE_12_ZOLTY, NpcID.II_IMPLING_TYPE_12_NEIL, NpcID.II_IMPLING_TYPE_12_YANNY,
		NpcID.II_IMPLING_TYPE_12_MATTY, NpcID.II_IMPLING_TYPE_12_STACE, NpcID.II_IMPLING_TYPE_12_IAN,
		NpcID.II_IMPLING_TYPE_12_JAMIE, NpcID.II_IMPLING_TYPE_12_DAMO, NpcID.II_IMPLING_TYPE_12_XANDER,
		NpcID.II_IMPLING_TYPE_12_STEVEO, NpcID.II_IMPLING_TYPE_12_STEWIE),
	DRAGON("Dragon", NpcID.II_IMPLING_TYPE_10, NpcID.II_IMPLING_TYPE_10_MAZE),
	LUCKY("Lucky", NpcID.II_IMPLING_TYPE_11, NpcID.II_IMPLING_TYPE_11_MAZE);

	/** Reverse lookup from NPC id to impling kind, built once from the constants above. */
	private static final Map<Integer, ImplingType> BY_NPC_ID = buildLookup();

	private final String displayName;

	private final int[] npcIds;

	ImplingType(String displayName, int... npcIds)
	{
		this.displayName = displayName;
		this.npcIds = npcIds;
	}

	/**
	 * Player-facing name of the impling kind, e.g. {@code "Ninja"}.
	 *
	 * @return the display name
	 */
	public String getDisplayName()
	{
		return displayName;
	}

	/**
	 * Finds the impling kind an NPC id belongs to.
	 *
	 * @param npcId the NPC's id
	 * @return the impling kind, or {@code null} when the NPC is not an impling
	 */
	public static ImplingType fromNpcId(int npcId)
	{
		return BY_NPC_ID.get(npcId);
	}

	private static Map<Integer, ImplingType> buildLookup()
	{
		Map<Integer, ImplingType> lookup = new HashMap<>();
		for (ImplingType type : values())
		{
			for (int id : type.npcIds)
				lookup.put(id, type);
		}

		return Collections.unmodifiableMap(lookup);
	}
}

