package com.oveduumnakal.implingpathfinder;

import java.awt.Point;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

import net.runelite.api.CollisionDataFlag;

/**
 * Cheapest-route search over one plane of the loaded scene's collision flags. Moves follow the game's rules: eight
 * directions, walls block the side they sit on, and a diagonal step needs both of its cardinal steps open.
 *
 * <p>Pushable tiles (Puro-Puro wheat) add one more kind of move: from a free tile, push straight through a run of
 * up to {@value #MAX_PUSH_DEPTH} pushable tiles to the free tile beyond. A push costs a fixed amount, so the search
 * takes it only when it beats walking around.
 */
public final class ScenePathfinder
{
	/** Cost value for a tile the search never reached. */
	public static final int UNREACHED = -1;

	/** Most pushable tiles one push can cross in a straight line. */
	static final int MAX_PUSH_DEPTH = 2;

	private static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL;

	private static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1};

	private static final int[] DY = {0, 0, -1, 1, -1, -1, 1, 1};

	/** The first four directions are the cardinal ones; pushes only go straight. */
	private static final int CARDINALS = 4;

	private final int width;

	private final int height;

	private final int[] cost;

	private final int[] parent;

	private ScenePathfinder(int width, int height)
	{
		this.width = width;
		this.height = height;
		this.cost = new int[width * height];
		this.parent = new int[width * height];
		Arrays.fill(cost, UNREACHED);
	}

	/**
	 * Runs one search from a start tile, reaching every tile the player can get to.
	 *
	 * @param flags collision flags indexed {@code [sceneX][sceneY]}
	 * @param pushable tiles that can be pushed through, indexed like {@code flags}; {@code null} for none
	 * @param startX scene x of the start tile
	 * @param startY scene y of the start tile
	 * @param stepCost cost of one walking step
	 * @param pushCost cost of one push through pushable tiles
	 * @return the finished search, ready for {@link #pathTo} lookups
	 */
	public static ScenePathfinder search(int[][] flags, boolean[][] pushable, int startX, int startY, int stepCost,
		int pushCost)
	{
		ScenePathfinder result = new ScenePathfinder(flags.length, flags.length == 0 ? 0 : flags[0].length);
		if (!result.inBounds(startX, startY))
			return result;

		int start = result.index(startX, startY);
		result.cost[start] = 0;
		result.parent[start] = start;
		PriorityQueue<Long> queue = new PriorityQueue<>();
		queue.add(entry(0, start));
		while (!queue.isEmpty())
		{
			long head = queue.poll();
			int current = (int) head;
			int currentCost = (int) (head >>> 32);
			if (currentCost != result.cost[current])
				continue;

			int x = current / result.height;
			int y = current % result.height;
			for (int dir = 0; dir < DX.length; dir++)
			{
				int nx = x + DX[dir];
				int ny = y + DY[dir];
				if (result.inBounds(nx, ny) && canMove(flags, x, y, DX[dir], DY[dir]))
					result.relax(queue, current, result.index(nx, ny), currentCost + stepCost);
			}

			if (pushable == null)
				continue;

			for (int dir = 0; dir < CARDINALS; dir++)
			{
				int landing = pushLanding(flags, pushable, x, y, DX[dir], DY[dir]);
				if (landing >= 0)
					result.relax(queue, current, landing, currentCost + pushCost);
			}
		}

		return result;
	}

	/**
	 * Cost of the cheapest route from the start to a tile.
	 *
	 * @param x scene x
	 * @param y scene y
	 * @return the route cost, or {@link #UNREACHED} when no route exists
	 */
	public int costTo(int x, int y)
	{
		if (!inBounds(x, y))
			return UNREACHED;

		return cost[index(x, y)];
	}

	/**
	 * The cheapest route to a goal tile, start tile first, with every tile a push crosses included so the route
	 * draws as one unbroken line. When the goal cannot be reached, the route ends at the reachable tile closest to
	 * it instead, so the player still gets a lead.
	 *
	 * @param goalX scene x of the goal
	 * @param goalY scene y of the goal
	 * @return the tiles on the route, start first; empty when nothing was reached
	 */
	public List<Point> pathTo(int goalX, int goalY)
	{
		int end = inBounds(goalX, goalY) && cost[index(goalX, goalY)] != UNREACHED
			? index(goalX, goalY)
			: closestReached(goalX, goalY);
		if (end < 0)
			return Collections.emptyList();

		List<Point> path = new ArrayList<>();
		int current = end;
		while (parent[current] != current)
		{
			addSegment(path, current, parent[current]);
			current = parent[current];
		}

		path.add(new Point(current / height, current % height));
		Collections.reverse(path);
		return path;
	}

	/**
	 * Whether a single step from one tile in a direction is allowed by the collision flags.
	 *
	 * @param flags collision flags indexed {@code [sceneX][sceneY]}
	 * @param x scene x of the tile stepped from
	 * @param y scene y of the tile stepped from
	 * @param dx x direction, -1, 0 or 1
	 * @param dy y direction, -1, 0 or 1
	 * @return true when the step is open
	 */
	static boolean canMove(int[][] flags, int x, int y, int dx, int dy)
	{
		int tx = x + dx;
		int ty = y + dy;
		if (dx == 0 || dy == 0)
			return (flags[tx][ty] & cardinalEntryMask(dx, dy)) == 0;

		return (flags[tx][ty] & diagonalEntryMask(dx, dy)) == 0
			&& (flags[tx][y] & cardinalEntryMask(dx, 0)) == 0
			&& (flags[x][ty] & cardinalEntryMask(0, dy)) == 0;
	}

	/**
	 * Where a push from a tile in a cardinal direction lands: straight through one or more pushable tiles onto the
	 * first open tile beyond them.
	 *
	 * @param flags collision flags indexed {@code [sceneX][sceneY]}
	 * @param pushable tiles that can be pushed through, indexed like {@code flags}
	 * @param x scene x of the tile pushed from
	 * @param y scene y of the tile pushed from
	 * @param dx x direction, -1, 0 or 1
	 * @param dy y direction, -1, 0 or 1
	 * @return the landing tile packed as {@code x * sceneHeight + y}, or -1 when no push is possible that way
	 */
	static int pushLanding(int[][] flags, boolean[][] pushable, int x, int y, int dx, int dy)
	{
		int sizeX = flags.length;
		int sizeY = flags[0].length;
		for (int depth = 1; depth <= MAX_PUSH_DEPTH; depth++)
		{
			int px = x + dx * depth;
			int py = y + dy * depth;
			if (px < 0 || py < 0 || px >= sizeX || py >= sizeY || !pushable[px][py])
				return -1;

			int lx = px + dx;
			int ly = py + dy;
			if (lx < 0 || ly < 0 || lx >= sizeX || ly >= sizeY)
				return -1;

			if (!pushable[lx][ly])
				return (flags[lx][ly] & cardinalEntryMask(dx, dy)) == 0 ? lx * sizeY + ly : -1;
		}

		return -1;
	}

	/**
	 * Flags on the destination tile that stop a straight step into it: a full block, or a wall on the side the
	 * step enters from.
	 */
	private static int cardinalEntryMask(int dx, int dy)
	{
		if (dx < 0)
			return BLOCKED | CollisionDataFlag.BLOCK_MOVEMENT_EAST;

		if (dx > 0)
			return BLOCKED | CollisionDataFlag.BLOCK_MOVEMENT_WEST;

		if (dy < 0)
			return BLOCKED | CollisionDataFlag.BLOCK_MOVEMENT_NORTH;

		return BLOCKED | CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
	}

	/** Flags on the destination tile that stop a diagonal step into it: a full block or any wall facing back. */
	private static int diagonalEntryMask(int dx, int dy)
	{
		int back = dx < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_EAST : CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		int up = dy < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH : CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
		int corner;
		if (dx < 0)
			corner = dy < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST : CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST;
		else
			corner = dy < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST : CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST;

		return BLOCKED | back | up | corner;
	}

	private static long entry(int cost, int index)
	{
		return (long) cost << 32 | index;
	}

	private void relax(PriorityQueue<Long> queue, int from, int to, int newCost)
	{
		if (cost[to] != UNREACHED && cost[to] <= newCost)
			return;

		cost[to] = newCost;
		parent[to] = from;
		queue.add(entry(newCost, to));
	}

	/** Adds {@code to} and, for a push, the tiles crossed on the way back to {@code from} (not {@code from} itself). */
	private void addSegment(List<Point> path, int to, int from)
	{
		int fromX = from / height;
		int fromY = from % height;
		int x = to / height;
		int y = to % height;
		int dx = Integer.signum(fromX - x);
		int dy = Integer.signum(fromY - y);
		while (x != fromX || y != fromY)
		{
			path.add(new Point(x, y));
			x += dx;
			y += dy;
		}
	}

	/** Index of the reached tile nearest a goal: tiles away first, then summed x and y gap, then route cost. */
	private int closestReached(int goalX, int goalY)
	{
		int best = -1;
		long bestScore = Long.MAX_VALUE;
		for (int i = 0; i < cost.length; i++)
		{
			if (cost[i] == UNREACHED)
				continue;

			int gapX = Math.abs(i / height - goalX);
			int gapY = Math.abs(i % height - goalY);
			long score = ((long) Math.max(gapX, gapY) << 40) | ((long) (gapX + gapY) << 20) | cost[i];
			if (score < bestScore)
			{
				best = i;
				bestScore = score;
			}
		}

		return best;
	}

	private boolean inBounds(int x, int y)
	{
		return x >= 0 && y >= 0 && x < width && y < height;
	}

	private int index(int x, int y)
	{
		return x * height + y;
	}
}

