package com.oveduumnakal.implingpathfinder;

import java.awt.Point;
import java.util.List;

import org.junit.Test;

import net.runelite.api.CollisionDataFlag;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Checks the walking search against hand-built collision grids. */
public class ScenePathfinderTest
{
	private static final int SIZE = 10;

	private static final int PUSH_COST = 16;

	private static ScenePathfinder walk(int[][] flags, int startX, int startY)
	{
		return ScenePathfinder.search(flags, null, startX, startY, 1, PUSH_COST);
	}

	/** A wheat wall along x = 5, one tile thick, every tile pushable. */
	private static boolean[][] wheatWall(int[][] flags)
	{
		boolean[][] pushable = new boolean[SIZE][SIZE];
		for (int y = 0; y < SIZE; y++)
		{
			flags[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;
			pushable[5][y] = true;
		}

		return pushable;
	}

	@Test
	public void openGroundWalksDiagonally()
	{
		int[][] flags = new int[SIZE][SIZE];
		ScenePathfinder search = walk(flags, 0, 0);

		List<Point> path = search.pathTo(4, 4);

		assertEquals(5, path.size());
		assertEquals(new Point(0, 0), path.get(0));
		assertEquals(new Point(4, 4), path.get(4));
		assertEquals(4, search.costTo(4, 4));
	}

	@Test
	public void blockedColumnForcesDetourThroughGap()
	{
		int[][] flags = new int[SIZE][SIZE];
		for (int y = 0; y < SIZE; y++)
		{
			if (y != 8)
				flags[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		}

		ScenePathfinder search = walk(flags, 2, 0);
		List<Point> path = search.pathTo(8, 0);

		assertTrue(path.contains(new Point(5, 8)));
		assertEquals(new Point(8, 0), path.get(path.size() - 1));
	}

	@Test
	public void wallBlocksOnlyItsSide()
	{
		int[][] flags = new int[SIZE][SIZE];
		flags[3][3] |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		flags[4][3] |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;

		assertFalse(ScenePathfinder.canMove(flags, 3, 3, 1, 0));
		assertFalse(ScenePathfinder.canMove(flags, 4, 3, -1, 0));
		assertTrue(ScenePathfinder.canMove(flags, 3, 3, 0, 1));
	}

	@Test
	public void diagonalNeedsBothCardinalStepsOpen()
	{
		int[][] flags = new int[SIZE][SIZE];
		flags[4][3] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;

		assertFalse(ScenePathfinder.canMove(flags, 3, 3, 1, 1));
		assertTrue(ScenePathfinder.canMove(flags, 3, 3, -1, 1));
	}

	@Test
	public void unreachableGoalEndsAtClosestTile()
	{
		int[][] flags = new int[SIZE][SIZE];
		for (int y = 0; y < SIZE; y++)
			flags[5][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;

		ScenePathfinder search = walk(flags, 0, 4);
		List<Point> path = search.pathTo(8, 4);

		assertEquals(ScenePathfinder.UNREACHED, search.costTo(8, 4));
		assertEquals(new Point(4, 4), path.get(path.size() - 1));
	}

	@Test
	public void startOutsideSceneReachesNothing()
	{
		ScenePathfinder search = walk(new int[SIZE][SIZE], -1, 0);

		assertTrue(search.pathTo(3, 3).isEmpty());
	}

	@Test
	public void pushCrossesWheatWhenWalkingAroundIsImpossible()
	{
		int[][] flags = new int[SIZE][SIZE];
		boolean[][] pushable = wheatWall(flags);

		ScenePathfinder search = ScenePathfinder.search(flags, pushable, 4, 4, 1, PUSH_COST);
		List<Point> path = search.pathTo(6, 4);

		assertEquals(PUSH_COST, search.costTo(6, 4));
		assertEquals(List.of(new Point(4, 4), new Point(5, 4), new Point(6, 4)), path);
	}

	@Test
	public void walkingAroundBeatsPushWhenShorter()
	{
		int[][] flags = new int[SIZE][SIZE];
		boolean[][] pushable = wheatWall(flags);
		flags[5][5] = 0;
		pushable[5][5] = false;

		ScenePathfinder search = ScenePathfinder.search(flags, pushable, 4, 4, 1, PUSH_COST);

		assertEquals(4, search.costTo(6, 4));
		assertFalse(search.pathTo(6, 4).contains(new Point(5, 4)));
	}

	@Test
	public void pushNeedsOpenLandingTile()
	{
		int[][] flags = new int[SIZE][SIZE];
		boolean[][] pushable = wheatWall(flags);
		flags[6][4] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;

		assertEquals(-1, ScenePathfinder.pushLanding(flags, pushable, 4, 4, 1, 0));
		assertEquals(6 * SIZE + 3, ScenePathfinder.pushLanding(flags, pushable, 4, 3, 1, 0));
	}

	@Test
	public void pushCrossesTwoThickWheat()
	{
		int[][] flags = new int[SIZE][SIZE];
		boolean[][] pushable = wheatWall(flags);
		flags[6][2] = CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;
		pushable[6][2] = true;

		assertEquals(7 * SIZE + 2, ScenePathfinder.pushLanding(flags, pushable, 4, 2, 1, 0));
	}
}
